class Sequence(object):
    def __init__(self, label, seq):
        self.label = label
        self.seq = seq

    def __len__(self):
        return len(self.seq)

    def fasta_str(self, interleaved=False):
        out_str = []
        if interleaved:
            out_str.extend(['>', self.label, '\n'])
            j = interleaved
            while j < len(self):
                out_str.append(self.seq[(j - interleaved):j])
                out_str.append('\n')
                j += interleaved
            out_str.append(self.seq[(j - interleaved):j])
            out_str.append('\n')
        else:
            out_str = ['>', self.label, '\n', self.seq, "\n"]
        return "".join(out_str)


class SequenceList(object):
    def __init__(self, input_fasta_file=None, indexed=False):
        self.sequences = []
        self.interleaved = False
        self.__dict = {}
        self.__indexed = indexed
        if input_fasta_file:
            self.read_fasta(input_fasta_file)
            if indexed:
                for go_s, seq in enumerate(self.sequences):
                    self.__dict[seq.label] = go_s

    def __len__(self):
        return len(self.sequences)

    def __iter__(self):
        for seq in self.sequences:
            yield seq

    def __getitem__(self, item):
        if isinstance(item, str) and self.__indexed:
            return self.sequences[self.__dict[item]]
        else:
            return self.sequences[item]

    def __contains__(self, item):
        if isinstance(item, str) and self.__indexed:
            return item in self.__dict
        else:
            return item in self.sequences

    def append(self, sequence):
        self.sequences.append(sequence)
        if self.__indexed:
            self.__dict[sequence.label] = len(self.sequences) - 1

    def remove(self, names):
        del_names = set(names)
        go_to = 0
        while go_to < len(self.sequences):
            if self.sequences[go_to].label in del_names:
                del_names.remove(self.sequences[go_to].label)
                del self.sequences[go_to]
            else:
                go_to += 1
        if del_names:
            for go_s, seq in enumerate(self.sequences):
                self.__dict[seq.label] = go_s
            sys.stdout.write("Warning: sequence(s) " + ",".join(sorted(del_names)) + " not found!\n")

    def read_fasta(self, fasta_file):
        fasta_file = open(fasta_file, 'r')
        this_line = fasta_file.readline()
        interleaved = 0
        while this_line:
            if this_line.startswith('>'):
                this_name = this_line[1:].strip()
                this_seq = ''
                this_line = fasta_file.readline()
                seq_line_count = 0
                while this_line and not this_line.startswith('>'):
                    if seq_line_count == 1:
                        interleaved = len(this_seq)
                    this_seq += this_line.strip()
                    this_line = fasta_file.readline()
                    seq_line_count += 1
                self.append(Sequence(this_name, this_seq))
            else:
                this_line = fasta_file.readline()
        fasta_file.close()
        self.interleaved = interleaved

    def write_fasta(self, fasta_file, overwrite=True, interleaved=None):
        if not overwrite:
            while os.path.exists(fasta_file):
                fasta_file = '.'.join(fasta_file.split('.')[:-1]) + '_.' + fasta_file.split('.')[-1]
        this_interleaved = self.interleaved if interleaved is None else interleaved
        fasta_file_handler = open(fasta_file, 'w')
        for seq in self:
            fasta_file_handler.write(seq.fasta_str(this_interleaved))
        fasta_file_handler.close()


class SeqKmerIndexer(object):
    def __init__(self, sequence, kmer, is_circular=False):
        self.__kmer = kmer
        if is_circular:
            self.__sequence = sequence + sequence[:kmer - 1]
            self.__len = len(sequence)
        else:
            self.__sequence = sequence
            self.__len = len(sequence) - kmer + 1

    def __len__(self):
        return self.__len

    def __getitem__(self, item):
        if -self.__len - 1 < item < -1:
            return self.__sequence[1 - self.__kmer + item: 1 + item]
        elif item == -1:
            return self.__sequence[1 - self.__kmer + item:]
        elif -1 < item < self.__len:
            return self.__sequence[item: item + self.__kmer]
        else:
            raise IndexError("index out of range")

    def __enumerate__(self):
        for i in range(self.__len):
            yield i, self.__getitem__(i)


def read_fasta(fasta_dir):
    names = []
    seqs = []
    interleaved = 0
    with open(fasta_dir) as fasta_input:
        this_line = fasta_input.readline()
        while this_line:
            if this_line.startswith(">"):
                names.append(this_line[1:].strip())
                this_seq = ""
                this_line = fasta_input.readline()
                seq_line_count = 0
                while this_line and not this_line.startswith(">"):
                    if seq_line_count == 1:
                        interleaved = len(this_seq)
                    this_seq += this_line.strip()
                    this_line = fasta_input.readline()
                    seq_line_count += 1
                seqs.append(this_seq)
            else:
                this_line = fasta_input.readline()
        fasta_input.close()
    return [names, seqs, interleaved]


